The main edits to RoutingMapScreen are applied. Still remaining in RoutingMapScreen:
1. NodeWidget rewrite — always clickable, visual states (muted red / volume cyan / "Añadir" hint)
2. OutputDetailSheet — new signature with isTesting, onTestSignal, onStopTest + test signal section
3. CreateOutputSheet composable — new
4. deviceTypeForNode helper

Then CalibrationScreen changes (export/import/delete), then build.

Let me apply these now. NodeWidget current code (from earlier full read):

```kotlin
@Composable
private fun NodeWidget(
    node: RoutingNode,
    outputs: List<OutputTarget>,
    onClick: () -> Unit
) {
    val allMuted = outputs.isNotEmpty() && outputs.all { it.isMuted }
    val hasOutputs = outputs.isNotEmpty()

    Column(
        horizontalAlignment = Alignment.CenterHorizontally,
        modifier = Modifier
            .height(44.dp)
            .let { base ->
                if (hasOutputs) {
                    base
                        .clip(RoundedCornerShape(8.dp))
                        .clickable { onClick() }
                } else base
            }
    ) {
        NodeIcon(node.type, node.isActive)
        Spacer(modifier = Modifier.height(2.dp))
        Text(
            text = node.name,
            style = MaterialTheme.typography.labelSmall,
            color = if (node.isActive) MaterialTheme.colorScheme.onSurface else MaterialTheme.colorScheme.onSurfaceVariant,
            fontWeight = FontWeight.Medium
        )
        if (hasOutputs) {
            Text(
                text = if (allMuted) "MUTE" else "%d%%".format(outputs.first().volumePercent),
                style = MaterialTheme.typography.labelSmall,
                color = if (allMuted) CoralAlert else CyanGlow,
                fontWeight = if (allMuted) FontWeight.Bold else FontWeight.Normal
            )
        } else if (node.spl > 0f) {
            Text(
                text = "%.0f dB".format(node.spl),
                style = MaterialTheme.typography.labelSmall,
                color = CyanGlow
            )
        }
    }
}
